const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{engine}=require('../pace_v0672.cjs');
const source='github-release/index.html',original=JSON.parse(fs.readFileSync('work/counter-threat-v0695/analysis.json','utf8')),{E,C}=engine(source);
const hash=x=>crypto.createHash('sha256').update(x).digest('hex'),sourceSHA256=hash(fs.readFileSync(source));
const prior=original.reports.flatMap(group=>group.report.runs.filter(r=>r.input.matchup==='new-new').map(r=>({...r,phase:group.plan.phase})));
assert.equal(prior.length,32);assert(!fs.existsSync(__dirname+'/audit.json'));
const report={version:'0.6.96',sourceSHA256,completed:false,runs:[]},save=()=>fs.writeFileSync(__dirname+'/audit.json',JSON.stringify(report,null,2)+'\n');save();
for(const expected of prior){
 let s,boards=0,commands=0,lateChoices=0,lateMoves=0,nearChoices=0,skippedCaptures=0,skippedLateCaptures=0,noAttacks=0,declinedAttacks=0;
 const examples=[],segments=[],activity={red:0,black:0};let segment=null;
 for(let index=0;index<expected.commands.length;index++){
  const [op,...args]=expected.commands[index];
  if(s?.phase==='board'){
   const raw=JSON.stringify(s),ranked=C.rankedActions(s),p=op==='pass'?null:E.get(s,args[0]),target=op==='move'?E.at(s,args[1],args[2]):null;
   const actual=ranked.find(a=>a.type===op&&a.id===args[0]&&(op==='rest'?a.card===args[1]:a.x===args[1]&&a.y===args[2]));
   assert(op==='pass'||actual,'actual move must be legal');boards++;if(p)activity[p.side]++;
   const late=s.quiet>=20;
   if(late){lateChoices++;if(!target)lateMoves++;if(actual&&actual.score<ranked[0].score-1e-8)nearChoices++;}
   const attacks=ranked.filter(a=>a.type==='move'&&E.at(s,a.x,a.y));
   if(!target){
    if(!attacks.length)noAttacks++;else declinedAttacks++;
    const safe=attacks.filter(a=>{
     const attacker=E.get(s,a.id),defender=E.at(s,a.x,a.y);if(defender.kind==='king'||a.score<=0)return false;
     const ctx=E.context(s,attacker,defender),outlook=C.battleOutlook(s,ctx);
     return outlook.finishes.length&&!C.captureLosesKing(s,ctx,outlook.finishes);
    });
    if(safe.length){
     skippedCaptures++;if(late)skippedLateCaptures++;
     const best=safe[0];assert(actual.score>=best.score-.06-1e-8);
     const king=s.pieces.find(q=>q.side===s.turn&&q.kind==='king'),kingThreats=s.pieces.filter(q=>q.side!==s.turn&&E.geometry(s,q,king.x,king.y,true)&&!C.battleOutlook(s,E.context(s,q,king)).counters.length).map(q=>q.id);
     examples.push({commandIndex:index,ply:s.ply+1,side:s.turn,quiet:s.quiet,selected:actual,capture:best,target:E.at(s,best.x,best.y).id,kingThreats});
    }
   }
   assert.equal(JSON.stringify(s),raw);
   if(!segment)segment={from:s.ply+1,actions:0};
  }
  const before=s?.ply,quiet=s?.quiet;
  if(op==='create')s=E.create(...args);else E[op](s,...args);commands++;
  if(s.ply>before){
   assert.equal(s.ply,before+1);segment.actions++;
   if(s.quiet===0&&quiet>=0){segments.push({...segment,to:s.ply,endsWithDamage:true});segment=null;}
  }
 }
 if(segment)segments.push({...segment,to:s.ply,endsWithDamage:false});
 assert.equal(s.phase,'ended');assert.equal(s.ply,boards);assert.equal(hash(JSON.stringify(s)),expected.terminalSHA256);assert.equal(s.winner,expected.winner);assert.equal(s.reason,expected.reason);
 report.runs.push({phase:expected.phase,input:expected.input,plies:s.ply,winner:s.winner,reason:s.reason,commands,boards,lateChoices,lateMoves,nearChoices,skippedCaptures,skippedLateCaptures,noAttacks,declinedAttacks,activity,segments,examples,final:s.pieces.map(p=>({id:p.id,side:p.side,kind:p.kind,hp:p.hp,x:p.x,y:p.y,learned:p.learned,exhausted:p.exhausted})),terminalSHA256:expected.terminalSHA256});
 save();if(report.runs.length%4===0)console.log(JSON.stringify({finished:report.runs.length,total:prior.length}));
}
assert.equal(hash(fs.readFileSync(source)),sourceSHA256);report.completed=true;
report.summary=['quick','full'].map(scenario=>{
 const rows=report.runs.filter(r=>r.input.scenario===scenario),sum=key=>rows.reduce((n,r)=>n+r[key],0),points=rows.flatMap(r=>r.examples);
 return {scenario,games:rows.length,boards:sum('boards'),commands:sum('commands'),meanPlies:sum('plies')/rows.length,maxPlies:Math.max(...rows.map(r=>r.plies)),draws:rows.filter(r=>r.winner==='draw').length,lateChoices:sum('lateChoices'),lateMoves:sum('lateMoves'),nearChoices:sum('nearChoices'),skippedCaptures:sum('skippedCaptures'),skippedLateCaptures:sum('skippedLateCaptures'),safeCaptureExamplesWithKingThreat:points.filter(p=>p.kingThreats.length).length,noAttackOptions:sum('noAttacks'),declinedAttacks:sum('declinedAttacks')};
});save();console.log(JSON.stringify(report.summary,null,2));

