const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{engine}=require('../pace_v0672.cjs');
const dir=__dirname,source='work/pace-after-v0696/baseline.html',{E,C}=engine(source),audit=JSON.parse(fs.readFileSync(dir+'/audit.json','utf8'));
const hash=x=>crypto.createHash('sha256').update(x).digest('hex'),copy=x=>JSON.parse(JSON.stringify(x));
assert(audit.completed);assert.equal(hash(fs.readFileSync(source)),audit.sourceSHA256);assert(!fs.existsSync(dir+'/opportunities.json'));
const original=JSON.parse(fs.readFileSync('work/counter-threat-v0695/analysis.json','utf8')),result={sourceSHA256:audit.sourceSHA256,completed:false,captures:[],late:[]};let branches=0;
for(const group of original.reports)for(const game of group.report.runs.filter(r=>r.input.matchup==='new-new')){
 const prior=audit.runs.find(r=>r.phase===group.plan.phase&&r.input.scenario===game.input.scenario&&r.input.replicate===game.input.replicate);assert(prior);
 let s;
 for(let index=0;index<game.commands.length;index++){
  const [op,...args]=game.commands[index];
  if(s?.phase==='board'){
   const example=prior.examples.find(row=>row.commandIndex===index),raw=JSON.stringify(s);
   if(example){
    const attacker=E.get(s,example.capture.id),defender=E.at(s,example.capture.x,example.capture.y),ctx=E.context(s,attacker,defender),finishes=C.battleOutlook(s,ctx).finishes;
    const choices=finishes.map(id=>({id,responses:C.choices(s,defender,ctx).map(reply=>{
     const next=copy(s);E.move(next,attacker.id,defender.x,defender.y);E.resolve(next,id,reply);branches++;
     assert(!E.get(next,defender.id)&&E.get(next,attacker.id)?.hp>0);assert.notEqual(next.phase,'duel');
     return {reply,hp:E.get(next,attacker.id).hp,phase:next.phase,winner:next.winner,kingLostNext:C.kingLostNext(next,attacker.side)};
    })}));
    const safe=choices.filter(option=>option.responses.every(reply=>!reply.kingLostNext&&(reply.phase!=='ended'||reply.winner===attacker.side||reply.winner==='draw'))).map(option=>option.id);
    result.captures.push({phase:group.plan.phase,input:game.input,...example,finishes:choices,safeChoices:safe});
   }
   const target=op==='move'?E.at(s,args[1],args[2]):null;
   if(s.quiet>=20&&!target){
    const attacks=C.actions(s).filter(a=>a.type==='move'&&E.at(s,a.x,a.y));
    let best=null;
    if(attacks.length){
     const ranked=C.rankedActions(s),battle=ranked.find(a=>a.type==='move'&&E.at(s,a.x,a.y)),p=E.get(s,battle.id),d=E.at(s,battle.x,battle.y),ctx=E.context(s,p,d),out=C.battleOutlook(s,ctx);
     best={...battle,attackerHp:p.hp,target:d.id,targetHp:d.hp,targetKind:d.kind,firstRoundFinishes:out.finishes,firstRoundCounters:out.counters,supportA:ctx.supportA,supportD:ctx.supportD};
     assert(battle.score<1000,'cannot silently skip an immediate forced win');
    }
    result.late.push({phase:group.plan.phase,input:game.input,commandIndex:index,ply:s.ply+1,side:s.turn,quiet:s.quiet,attackOptions:attacks.length,best});
   }
   assert.equal(JSON.stringify(s),raw);
  }
  if(op==='create')s=E.create(...args);else E[op](s,...args);
 }
 assert.equal(hash(JSON.stringify(s)),game.terminalSHA256);
}
assert.equal(result.captures.length,audit.runs.reduce((n,r)=>n+r.examples.length,0));
assert.equal(result.late.length,audit.runs.reduce((n,r)=>n+r.lateMoves,0));
result.completed=true;result.actualCaptureBranches=branches;
result.summary=['quick','full'].map(scenario=>{
 const rows=result.late.filter(r=>r.input.scenario===scenario),captures=result.captures.filter(r=>r.input.scenario===scenario);
 return {scenario,lateNonBattleChoices:rows.length,noAttackOptions:rows.filter(r=>!r.attackOptions).length,positiveBestAttack:rows.filter(r=>r.best?.score>0).length,nonPositiveBestAttack:rows.filter(r=>r.best&&r.best.score<=0).length,bestAttackCanBeCountered:rows.filter(r=>r.best?.firstRoundCounters.length).length,captureExamples:captures.length,capturesWithFullSafeChoice:captures.filter(r=>r.safeChoices.length).length,lateFullSafeChoices:captures.filter(r=>r.quiet>=20&&r.safeChoices.length).length};
});
fs.writeFileSync(dir+'/opportunities.json',JSON.stringify(result,null,2)+'\n');console.log(JSON.stringify({actualCaptureBranches:branches,summary:result.summary},null,2));

