const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{play,engine}=require('../pace_v0672.cjs');
const dir=__dirname,baseline='work/pace-after-v0696/baseline.html',html=fs.readFileSync(baseline,'utf8'),hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const traces=JSON.parse(fs.readFileSync(dir+'/traces.json','utf8')),opportunities=JSON.parse(fs.readFileSync(dir+'/opportunities.json','utf8'));
assert(traces.completed&&opportunities.completed);assert.equal(hash(fs.readFileSync(baseline)),traces.sourceSHA256);assert(!fs.existsSync(dir+'/branches.json'));
const report={version:'0.6.96',sourceSHA256:traces.sourceSHA256,method:'Longest recorded self-play in each scenario; force its first declined first-round capture once, keep the original random draw and all later decisions.',plan:[],runs:[],completed:false};
for(const expected of traces.runs){
 const row=opportunities.captures.find(r=>r.input.scenario===expected.input.scenario&&r.input.seed===expected.input.seed&&r.safeChoices.length);assert(row);
 const forced={...row.capture},patch=`\n(()=>{const choose=YiwuComputer.board;let replaced=false;YiwuComputer.board=(s,rng,difficulty)=>{const chosen=choose(s,rng,difficulty);if(!replaced&&s.ply===${row.ply-1}&&s.turn===${JSON.stringify(row.side)}){replaced=true;return ${JSON.stringify(forced)};}return chosen;};})();\n`;
 const scripts=[...html.matchAll(/<script[^>]*>([\s\S]*?)<\/script>/g)],computer=scripts[1],at=computer.index+computer[0].length-'</script>'.length,candidate=html.slice(0,at)+patch+html.slice(at),file='work/pace-after-v0696/branch-'+row.input.scenario+'.html';
 fs.writeFileSync(file,candidate);report.plan.push({input:expected.input,ply:row.ply,commandIndex:row.commandIndex,forced,safeChoices:row.safeChoices,sourceSHA256:hash(candidate),file,baseline:{plies:expected.plies,winner:expected.winner,reason:expected.reason}});
}
const save=()=>fs.writeFileSync(dir+'/branches.json',JSON.stringify(report,null,2)+'\n');save();
for(let i=0;i<report.plan.length;i++){
 const plan=report.plan[i],expected=traces.runs[i],{E,C}=engine(plan.file);let s;
 for(const [op,...args]of expected.commands.slice(0,plan.commandIndex)){if(op==='create')s=E.create(...args);else E[op](s,...args);}
 E.move(s,plan.forced.id,plan.forced.x,plan.forced.y);const initialPlan=JSON.parse(JSON.stringify(C.combatPlan(s,E.get(s,plan.forced.id).side)));
 assert(initialPlan.every(option=>plan.safeChoices.includes(option.id)),'forced branch must use a verified first-round capture plan');
 const run=play(expected.input,plan.file,true);
 assert.deepEqual(run.commands.slice(0,plan.commandIndex),expected.commands.slice(0,plan.commandIndex));
 assert.deepEqual(run.commands[plan.commandIndex],['move',plan.forced.id,plan.forced.x,plan.forced.y]);
 assert.notDeepEqual(run.commands[plan.commandIndex],expected.commands[plan.commandIndex]);
 let final;for(const [op,...args]of run.commands){if(op==='create')final=E.create(...args);else E[op](final,...args);}assert.equal(final.phase,'ended');assert.equal(final.winner,run.winner);assert.equal(final.ply,run.plies);
 report.runs.push({...run,initialPlan,terminalSHA256:hash(JSON.stringify(final))});save();console.log(JSON.stringify({scenario:run.input.scenario,forcedPly:plan.ply,baseline:plan.baseline,counterfactual:{plies:run.plies,winner:run.winner,reason:run.reason,battles:run.battles,reversals:run.reversals}}));
}
assert.equal(hash(fs.readFileSync(baseline)),report.sourceSHA256);report.completed=true;save();

