const fs=require('node:fs'),assert=require('node:assert/strict'),crypto=require('node:crypto'),{engine}=require('../pace_v0672.cjs');
const dir=__dirname,read=name=>JSON.parse(fs.readFileSync(dir+'/'+name,'utf8')),hash=x=>crypto.createHash('sha256').update(x).digest('hex');
const baseline=fs.readFileSync(dir+'/baseline.html'),entry=fs.readFileSync('github-release/index.html'),{E,C}=engine('work/pace-after-v0696/baseline.html');
assert.equal(hash(entry),'398d075cb33858a053b6c02f57b1f224fe20af0420ffec7b9aa72eba9b8f6bd1');assert.deepEqual(entry,baseline);assert.deepEqual(entry,fs.readFileSync('outputs/弈武.html'));
const audit=read('audit.json'),opportunities=read('opportunities.json'),traces=read('traces.json'),branches=read('branches.json');
for(const report of [audit,opportunities,traces,branches]){assert(report.completed);assert.equal(report.sourceSHA256,hash(entry));}
const upstreamBytes=fs.readFileSync('github-release/docs/data/counter-threat-0.6.96.json'),upstream=JSON.parse(upstreamBytes);
const originals=upstream.candidates.accepted.reports.flatMap(group=>group.report.runs.filter(r=>r.input.matchup==='new-new').map(r=>({...r,phase:group.plan.phase})));
assert.equal(originals.length,32);assert.equal(audit.runs.length,32);assert.equal(traces.runs.length,2);assert.equal(branches.runs.length,2);
let instructions=0;
function replay(row){
 let s,initial,spent;const damage={};
 for(const [op,...args]of row.commands){
  if(op==='create'){s=E.create(...args);initial=s.pieces.reduce((n,p)=>n+p.hp,0);for(const p of s.pieces)damage[p.id]=0;}
  else{
   if(op==='resolve'){const a=E.get(s,s.duel.a),d=E.get(s,s.duel.d),r=E.roundDamage(s.duel,...args);damage[a.id]+=Math.min(d.hp,r.toD);damage[d.id]+=Math.min(a.hp,r.toA);}
   E[op](s,...args);
   if(op==='start'){assert.equal(s.budget.red,0);assert.equal(s.budget.black,0);assert(s.pieces.every(p=>p.learned.length<=2));spent=s.points;}
  }
  instructions++;
 }
 assert(spent);assert.equal(s.phase,'ended');assert.equal(s.ply,row.plies);assert.equal(s.winner,row.winner);assert.equal(s.reason,row.reason);assert.equal(hash(JSON.stringify(s)),row.terminalSHA256);
 assert.equal(Object.values(damage).reduce((n,x)=>n+x,0),initial-s.pieces.reduce((n,p)=>n+p.hp,0));return damage;
}
const replayed=originals.map(row=>({phase:row.phase,input:row.input,terminalSHA256:row.terminalSHA256,actualDamage:replay(row)}));
assert.equal(instructions,7477);assert.equal(audit.runs.reduce((n,r)=>n+r.boards,0),5297);
for(const row of traces.runs){const original=originals.find(r=>r.input.scenario===row.input.scenario&&r.input.seed===row.input.seed);assert(original);assert.deepEqual(row.commands,original.commands);assert.equal(row.plies,original.plies);}
const branchVerification=branches.runs.map((run,i)=>{
 const plan=branches.plan[i],prior=traces.runs[i];assert.equal(hash(fs.readFileSync(plan.file)),plan.sourceSHA256);
 assert.deepEqual(run.commands.slice(0,plan.commandIndex),prior.commands.slice(0,plan.commandIndex));assert.deepEqual(run.commands[plan.commandIndex],['move',plan.forced.id,plan.forced.x,plan.forced.y]);
 let s;for(const [op,...args]of prior.commands.slice(0,plan.commandIndex)){if(op==='create')s=E.create(...args);else E[op](s,...args);}
 E.move(s,plan.forced.id,plan.forced.x,plan.forced.y);assert.deepEqual(JSON.parse(JSON.stringify(C.combatPlan(s,E.get(s,plan.forced.id).side))),run.initialPlan);
 return {input:run.input,actualDamage:replay(run),terminalSHA256:run.terminalSHA256};
});
assert.equal(opportunities.actualCaptureBranches,194);assert.equal(opportunities.captures.length,20);assert(opportunities.captures.every(r=>r.safeChoices.length&&r.quiet<20));
assert.equal(opportunities.late.length,1557);assert.equal(opportunities.late.filter(r=>!r.attackOptions).length,1079);assert.equal(opportunities.late.filter(r=>r.best?.score>0).length,87);
const sourceFiles=['trace.cjs','audit.cjs','opportunities.cjs','branch.cjs','verify-and-package.cjs'],sources=Object.fromEntries(sourceFiles.map(name=>{const source=fs.readFileSync(dir+'/'+name);return [name,{sha256:hash(source),source:source.toString('utf8')}];}));
const data={version:'0.6.96',baselineCommit:'3671a7e91416e337a2fc1201a022f5228610828b',entrySHA256:hash(entry),upstreamRecords:{file:'counter-threat-0.6.96.json',sha256:hash(upstreamBytes),selection:'candidates.accepted.reports[*].report.runs where input.matchup is new-new'},audit,opportunities,longestReplays:traces,exploratoryBranches:branches,sources,verification:{recordedGames:32,recordedCommands:7477,recordedBoardActions:5297,exactLongestReruns:2,exploratoryBranches:2,replayedCommandsIncludingBranches:instructions,entryUnchanged:true,mirrorMatches:true,inputUnchanged:true,allNaturallyEnded:true,allTerminalHashesMatch:true,allDamageMatches:true,records:replayed,branchVerification}};
const encoded=JSON.stringify(data)+'\n';assert(!encoded.includes('\ufffd'));fs.writeFileSync('github-release/docs/data/pace-audit-0.6.96.json',encoded);
fs.writeFileSync(dir+'/verification.json',JSON.stringify(data.verification,null,2)+'\n');console.log(JSON.stringify({...data.verification,records:undefined,branchVerification:undefined,bytes:Buffer.byteLength(encoded)}));
